#!/usr/bin/env node
// Record the TypeScript half of suites/provider-rate-limits/cases.json.
//
// The reference's half is generated by tools/generate-provider-rate-limits.php.
// This suite is a `security-corpus`, so there is no `expect` to compare against:
// each row records what every language PRODUCED and the three answers are the
// finding. That only means anything if every column was EXECUTED, so this runs
// the port rather than transcribing a reading of its source.
//
//   node tools/record-provider-rate-limits.mjs
//   node tools/record-provider-rate-limits.mjs --check
//
// It imports prism-ts from the sibling checkout in the `.agi` envelope, the same
// way the PHP generator reaches for the reference's autoloader. That is a
// GENERATOR's licence and not a loader's — loaders must find fixtures inside
// their own published artifact, and nothing here is shipped.
//
// PRISM_TS_DIST overrides the location. `npm run build` in prism-ts first: this
// reads dist/, because dist/ is what consumers get.

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const check = process.argv.includes('--check');
const dist = resolve(process.env.PRISM_TS_DIST ?? join(root, '..', 'prism-ts', 'dist'));

if (!existsSync(join(dist, 'index.js'))) {
  console.error(`No prism-ts build at ${dist}. Run \`npm run build\` there, or set PRISM_TS_DIST.`);
  process.exit(3);
}

const load = (path) => import(pathToFileURL(join(dist, path)).href);

const readers = {
  anthropic: (await load('providers/anthropic/rate-limits.js')).parseRateLimits,
  mistral: (await load('providers/mistral/rate-limits.js')).parseRateLimits,
  openai: (await load('providers/openai/rate-limits.js')).parseRateLimits,
};

const casesPath = join(root, 'suites', 'provider-rate-limits', 'cases.json');
const document = JSON.parse(readFileSync(casesPath, 'utf8'));

// The clock is FROZEN per row. Two of the three providers report a reset as a
// duration from now, and both read `Date.now()` directly rather than taking an
// injectable clock — so freezing it is the only way to record a value that is
// still true tomorrow. Restored after every row; a generator that left a fake
// clock installed would be measuring itself.
const realNow = Date.now;

function run(entry) {
  const { provider, headers, now } = entry.given;
  Date.now = () => now * 1000;

  try {
    // Header names are handed over EXACTLY as the row wrote them, case
    // included. Lower-casing here would answer prl-0008 in this file instead of
    // in the port, which is the row about a title-casing proxy.
    const buckets = readers[provider](headers).map((limit) => limit.toObject());

    return { outcome: 'ok', buckets };
  } catch {
    return { outcome: 'raised', buckets: null };
  } finally {
    Date.now = realNow;
  }
}

const stale = [];

for (const entry of document.cases) {
  const produced = run(entry);
  const recorded = entry.result.ts ?? null;

  if (JSON.stringify(recorded) !== JSON.stringify(produced)) {
    stale.push(`${entry.id}: recorded ${JSON.stringify(recorded)}, prism-ts produces ${JSON.stringify(produced)}`);
  }

  entry.result.ts = produced;
}

// Derived from whichever columns exist, never asserted. A row cannot be marked
// as agreeing by an editor who wanted it to.
for (const entry of document.cases) {
  const answers = Object.values(entry.result).filter((answer) => answer !== null);

  entry.agrees =
    answers.length > 1 && new Set(answers.map((answer) => JSON.stringify(answer))).size === 1;
}

if (check) {
  if (stale.length > 0) {
    console.error(`Stale TypeScript rows in provider-rate-limits:\n  ${stale.join('\n  ')}`);
    process.exit(1);
  }

  console.error('provider-rate-limits: every TypeScript row matches prism-ts.');
  process.exit(0);
}

writeFileSync(casesPath, `${JSON.stringify(document, null, 4)}\n`);

console.error(
  stale.length === 0
    ? 'provider-rate-limits: no change.'
    : `provider-rate-limits: rewrote ${stale.length} TypeScript row(s).`,
);
